  ui_story_5030_50300003_22_dialog_content = "¡Por supuesto que no! ¡¿Por qué clase de monstruos nos tomas?!",
  ui_story_5030_50300003_23_dialog_content = "¡Nuestro plan es mucho más técnico que eso!",
  ui_story_5030_50300003_24_dialog_content = "Bueno, no puedo decir que no tengo mis dudas... Pero supongo que no estaría de más escucharlos...",
  ui_story_5030_50300003_25_dialog_content = "¡Ja ja! ¡Ese es el espíritu!",
  ui_story_5030_50300003_26_dialog_content = "Creo que es hora de compartir esa historia con nuestra amiga, Merylt. ¿No estás de acuerdo?",
  ui_story_5030_50300003_27_dialog_content = "Eh... ¿Historia? ¿Que historia?",
  ui_story_5030_50300003_28_dialog_content = "Solo un poco de contexto, para que aprecies completamente todo lo que hemos hecho para ayudarte, ¡es todo!",
  ui_story_5030_50300003_29_dialog_content = "¡Ejem! ¡Adelante, Meryl! ¡Cuéntale la historia!",
  ui_story_5030_50300003_30_dialog_content = "UH oh...!",
  ui_story_5030_50300003_31_dialog_content = "¡Oye! Estabas bien con PlayerName hace solo un segundo, ¿por qué de repente te callas ahora?",
  ui_story_5030_50300003_32_dialog_content = "¡Shhh! Deja que ella cuente la historia, ¿quieres?",
  ui_story_5030_50300003_33_dialog_content = "AA hace mucho, mucho tiempo...",
  ui_story_5030_50300003_34_dialog_content = "En un rincón lejano y escondido de Astra, había una vez una reina brutal.",
  ui_story_5030_50300003_35_dialog_content = "La reina había gobernado este lugar durante décadas y sus súbditos habían vivido vidas pacíficas y autosuficientes bajo su reinado.",
  ui_story_5030_50300003_36_dialog_content = "Pero cuando la reina cumplió sesenta años... La máscara cayó, y su falsa paz con ella.",
  ui_story_5030_50300003_37_dialog_content = "¡¿Cómo podría ser esto?! No importa lo que haga, ¡no puedo hacer que estas arrugas desaparezcan!",
  ui_story_5030_50300003_38_dialog_content = "No... no puedo envejecer así...",
  ui_story_5030_50300003_39_dialog_content = "¡Mi pueblo solo puede llevar vidas felices y pacíficas bajo mi gobierno!",
  ui_story_5030_50300003_40_dialog_content = "¡Dime! ¿Qué debo hacer para prolongar mi vida y mi reinado sobre estas tierras?",
  ui_story_5030_50300003_41_dialog_content = "¡Oh!",
  ui_story_5030_50300003_42_dialog_content = "Hay una manera...",
  ui_story_5030_50300003_43_dialog_content = "Una técnica prohibida mencionada solo en las leyendas...",
  ui_story_5030_50300003_44_dialog_content = "Sumergiéndose en la sangre vital de los niños y niñas...",
  ui_story_5030_50300003_45_dialog_content = "Y renunciar a la comida en favor de su preciosa y juvenil esencia...",
  ui_story_5030_50300003_46_dialog_content = "A partir de ese día, la vida de sus súbditos cambió para siempre.",
  ui_story_5030_50300003_47_dialog_content = "Los niños comenzaron a desaparecer ante sus propios ojos, y el caos pronto descendió sobre la tierra.",
  ui_story_5030_50300003_48_dialog_content = "¿No había nada que pudiera detener la locura? ¿Nada en absoluto?",
  ui_story_5030_50300003_49_dialog_content = "La respuesta pronto comenzó a sonar desde lo más profundo de los corazones de todos los sobrevivientes del reino...",
  ui_story_5030_50300003_50_dialog_content = "¡Resistir! ¡Revuelta! ¡Solo al derrocar a la reina malvada finalmente conocerían la paz una vez más!",
  ui_story_5030_50300003_51_dialog_content = "...",
  ui_story_5030_50300003_52_dialog_content = "...",
  ui_story_5030_50300003_53_dialog_content = "Y, efectivamente, la tiranía de la reina finalmente fue detenida por las personas a las que ella buscaba desesperadamente para seguir gobernando.",
  ui_story_5030_50300003_54_dialog_content = "Con el tiempo, las sonrisas reaparecieron en los rostros de los niños, mientras la paz y la seguridad volvían al reino una vez más.",
  ui_story_5030_50300003_55_dialog_content = "Pero...",
  ui_story_5030_50300003_56_dialog_content = "Aunque las ambiciones de la reina por la vida eterna estaban impregnadas de violencia y terror...",
  ui_story_5030_50300003_57_dialog_content = "Aquellos con mentes más agudas pueden aprender algo valioso de su ejemplo...",
  ui_story_5030_50300003_58_dialog_content = "El arte de la extracción.",
  ui_story_5030_50300003_59_dialog_content = "De las plantas somos capaces de extraer su esencia y crear todo tipo de condimentos e ingredientes.",
  ui_story_5030_50300003_60_dialog_content = "Este es el regalo que les ofrecemos hoy.",
  ui_story_5030_50300003_61_dialog_content = "Increíble... ¡Merylt fue capaz de contar toda la historia frente a PlayerName sin perder el ritmo!",
  ui_story_5030_50300003_62_dialog_content = "¡Esto requiere una celebración!",
  ui_story_5030_50300003_63_dialog_content = "¡Aquí! ¡Toma un soplo!",
  ui_story_5030_50300003_64_dialog_content = "¡E-Espera un minuto! ¡No me mires así! ¡Me esta poniendo paranoico!",
  ui_story_5030_50300003_65_dialog_content = "No me malinterpretes, estoy agradecido por el regalo, pero solo tengo que asegurarme...",
  ui_story_5030_50300003_66_dialog_content = "E-Esa historia sobre la reina malvada y lo que les hizo a esos niños... No está basada en una historia real, ¿verdad?",
  ui_story_5030_50300003_66X_dialog_content = "¡Esta historia que estás contando da demasiado miedo!",
  ui_story_5030_50300003_67_dialog_content = "¿Quién puede decir? Siempre hay algo de verdad escondido en cada leyenda, después de todo...",
  ui_story_5030_50300003_68_dialog_content = "De todos modos, te trajimos tu regalo, así que date prisa y tómalo, ¿de acuerdo?",
  ui_story_5030_50300003_69_dialog_content = "P-Podría ser...",
  ui_story_5030_50300003_70_dialog_content = "¿Será que... no te gusta nuestro regalo?",
  ui_story_5030_50300003_71_dialog_content = "¡Ay! ¡N-No, me gusta!",
  ui_story_5030_50300003_72_dialog_content = "Solo estaba preguntando sobre la historia, ¡eso es todo!",
  ui_story_5030_50300003_73_dialog_content = "Quiero decir, fue bastante aterrador, después de todo.",
  ui_story_5030_50300003_74_dialog_content = "Querías que lo oliera, ¿verdad? Aquí va...",
  ui_story_5030_50300003_75_dialog_content = "Espera, ¡esto huele increíble!",
  ui_story_5030_50300003_76_dialog_content = "¡Sí, sí!",
  ui_story_5030_50300003_77_dialog_content = "Aunque, todavía tengo que preguntar... ¿Qué tipo de planta usaste para hacer esto?",
  ui_story_5030_50300003_78_dialog_content = "Siento que no podré usarlo correctamente a menos que sepa exactamente de qué está hecho.",
  ui_story_5030_50300003_79_dialog_content = "La gente lo comerá en mi cocina, así que tengo que tomar este tipo de cosas en serio.",
  ui_story_5030_50300003_80_dialog_content = "Jeje!",
  ui_story_5030_50300003_81_dialog_content = "Me tomó casi un día apestoso, pero afortunadamente... ¡Parece que ningún animal resultó dañado en la elaboración de ese condimento!",
  ui_story_5030_50300003_82_dialog_content = "¿Fia?",
  ui_story_5030_50300003_83_dialog_content = "Has estado espiándonos todo este tiempo, ¿no es así?",
  ui_story_5030_50300003_84_dialog_content = "¿Qué? ¿Cómo podría ser \"escuchar a escondidas\", cuando esto es claramente un espacio público?",
  ui_story_5030_50300003_85_dialog_content = "Solo vine a probar todas las delicias que están en oferta. ¿Está tan mal?",
  ui_story_5030_50300003_86_dialog_content = "Pero para asegurarte de que el condimento que te dieron es realmente vegetal, tendrás que...",
  ui_story_5030_50300003_87_dialog_content = "¡Tendrás que dejarme olerlo también!",
  ui_story_5030_50300003_88_dialog_content = "¡Oye, imbécil! Ese es el regalo de Merylt para PlayerName, ¡así que guárdate tus mugrientos guantes para ti!",
  ui_story_5030_50300003_89_dialog_content = "*Sollozando* ¡Pero... pero...!",
  ui_story_5030_50300003_90_dialog_content = "(¡¿Realmente está rompiendo las lágrimas falsas por esto?!)",
  ui_story_5030_50300003_91_dialog_content = "Yo... solo quería oler un poco, eso es todo... nunca lo robaría ni nada...",
  ui_story_5030_50300003_92_dialog_content = "Urgh... ¡Por qué, pequeño mocoso irritante!",
  ui_story_5030_50300003_93_dialog_content = "Está bien, Subli.",
  ui_story_5030_50300003_94_dialog_content = "Adelante, huélelo si quieres, Fia.",
  ui_story_5030_50300003_95_dialog_content = "Puedo asegurarles que esto fue hecho usando plantas que recolecté minuciosamente durante un largo período de tiempo.",
  ui_story_5030_50300003_96_dialog_content = "¿Ver? Huele maravilloso, ¿no?",
  ui_story_5030_50300003_97_dialog_content = "¡Si, tienes razón!",
  ui_story_5030_50300003_98_dialog_content = "Y también tiene una especie de fragancia vegetal...",
  ui_story_5030_50300003_99_dialog_content = "¡Eso lo resuelve, PlayerName! ¡Este condimento pasa mi evaluación profesional!",
  ui_story_5030_50300003_100_dialog_content = "Nunca pedí una \"evaluación profesional\"... Tú eres el que no lo dejaría pasar...",
  ui_story_5030_50300003_101_dialog_content = "¡No tengo idea de lo que estás hablando!",
  ui_story_5030_50300003_102_dialog_content = "De todos modos, gracias, Merylt.",
  ui_story_5030_50300003_103_dialog_content = "¡N-Ni lo menciones...!",
  ui_story_5030_50300003_104_dialog_content = "Ahora veamos qué le hace esto al sabor de mi caldo cuando lo agrego...",
  ui_story_5030_50300003_105_dialog_content = "Oye, ¿qué es ese olor?",
  ui_story_5030_50300003_106_dialog_content = "¡Huele increíble!",
  ui_story_5030_50300003_107_dialog_content = "¡Creo que viene de allí! ¡Vamos, echemos un vistazo!",
  ui_story_5030_50300004_1_dialog_content = "¡Número 78! ¡Tus fideos están listos!",
  ui_story_5030_50300004_2_dialog_content = "¡Número 78! ¿Número 78?",
  ui_story_5030_50300004_3_dialog_content = "Número 78, su orden es—",
  ui_story_5030_50300004_4_dialog_content = "¿Qué es este lío? Este lugar es un caos total... ¡No tengo idea de dónde comienza o termina la fila!",
  ui_story_5030_50300004_5_dialog_content = "¡Lo siento por eso! El final de la línea es...",
  ui_story_5030_50300004_6_dialog_content = "Mierda... ¡Yo tampoco estoy tan seguro de dónde está!",
  ui_story_5030_50300004_7_dialog_content = "¿Qué tal esto? Dime lo que te gustaría y llamaré a tu número cuando tu pedido esté listo.",
  ui_story_5030_50300004_8_dialog_content = "Bueno, ¿cuántos pedidos están por delante del mío?",
  ui_story_5030_50300004_9_dialog_content = "Déjame ver...",
  ui_story_5030_50300004_10_dialog_content = "Bueno, serías el número 103, así que... T-Twenty órdenes, más o menos.",
  ui_story_5030_50300004_11_dialog_content = "¡Oye! ¿Se equivocó en mi pedido o algo así?",
  ui_story_5030_50300004_12_dialog_content = "¡Claramente pedí sopa de fideos, pero me serviste fideos con salsa de carne!",
  ui_story_5030_50300004_13_dialog_content = "M-Mis disculpas! Déjame hacerte otro tazón...",
  ui_story_5030_50300004_14_dialog_content = "¡Oye! ¡Sin cortar la línea! ¡Hemos estado esperando aquí bastante tiempo, tal como están las cosas!",
  ui_story_5030_50300004_15_dialog_content = "(Todo es un desastre total en este momento... ¡Esto es malo!)",
  ui_story_5030_50300004_16_dialog_content = "(¿Debería dejar de tomar nuevos pedidos? Si lo hago, puedo concentrarme en los clientes que ya están esperando su comida).",
  ui_story_5030_50300004_17_dialog_content = "Aquí está tu fideo.",
  ui_story_5030_50300004_18_dialog_content = "Hmph. Eso es más bien.",
  ui_story_5030_50300004_19_dialog_content = "Tus fideos también estarán listos tan pronto como la tetera hierva.",
  ui_story_5030_50300004_20_dialog_content = "¡Piedra solar! Un poco más, ¿si quieres?",
  ui_story_5030_50300004_21_dialog_content = "Tu pedido también está listo. Todo lo que falta son los ingredientes... Ahí lo tienes.",
  ui_story_5030_50300004_22_dialog_content = "Jeje! ¡Siempre sabe mejor cuando está fresco!",
  ui_story_5030_50300004_23_dialog_content = "Parece que ese puesto está sacando pedidos un poco más rápido ahora.",
  ui_story_5030_50300004_24_dialog_content = "Parece de esa manera. ¡La fila también se está moviendo mucho más rápido!",
  ui_story_5030_50300004_25_dialog_content = "...",
  ui_story_5030_50300004_26_dialog_content = "L-Leona?!",
  ui_story_5030_50300004_27_dialog_content = "¿Por qué tan sorprendido? Tus ojos casi se salen de tus órbitas, ¿sabes?",
  ui_story_5030_50300004_28_dialog_content = "L-Lo siento, no sabía de qué sorprenderme primero...",
  ui_story_5030_50300004_29_dialog_content = "Verte visitar este lugar, o verte pedirle a Sunstone que hierva agua con su aliento llameante.",
  ui_story_5030_50300004_30_dialog_content = "No me importa",
  ui_story_5030_50300004_31_dialog_content = "Vi que la cola para este puesto estaba completamente fuera de control, así que tenía curiosidad por ver qué había en oferta.",
  ui_story_5030_50300004_32_dialog_content = "Yo tampoco esperaba verte aquí.",
  ui_story_5030_50300004_33_dialog_content = "O verte tambaleándote y tambaleándote así. Nunca había visto este lado tuyo antes.",
  ui_story_5030_50300004_34_dialog_content = "Eh... Jajaja...",
  ui_story_5030_50300004_35_dialog_content = "Estaba un poco abrumado por la gran cantidad de clientes, eso es todo.",
  ui_story_5030_50300004_36_dialog_content = "Ya veo... Con Sunstone ayudándote a hervir agua, tu eficiencia debería aumentar considerablemente.",
  ui_story_5030_50300004_37_dialog_content = "Aunque... ¿Soy solo yo, o la multitud alrededor del puesto es cada vez más grande?",
  ui_story_5030_50300004_38_dialog_content = "Oye, tú ahí.",
  ui_story_5030_50300004_39_dialog_content = "La línea es de esa manera. ¿Qué haces dando vueltas por aquí?",
  ui_story_5030_50300004_40_dialog_content = "Oh, Leona? Pienso...",
  ui_story_5030_50300004_41_dialog_content = "Creo que están aquí para ver el \"acto de escupir fuego\" de Sunstone.",
  ui_story_5030_50300004_42_dialog_content = "¿Qué podría ser tan interesante sobre Sunstone respirando fuego? Es perfectamente normal.",
  ui_story_5030_50300004_43_dialog_content = "U-Um...",
  ui_story_5030_50300004_44_dialog_content = "Tal vez para ti, pero supongo que no todos han tenido la oportunidad de ver un dragón real antes.",
  ui_story_5030_50300004_45_dialog_content = "Está bien.",
  ui_story_5030_50300004_46_dialog_content = "¡Mirar! ¡Un dragón que escupe fuego!",
  ui_story_5030_50300004_47_dialog_content = "¿Alguna vez has visto uno antes?",
  ui_story_5030_50300004_48_dialog_content = "¡No! He escuchado muchas historias sobre ellos, ¡pero esta es la primera vez que veo uno vivo en persona!",
  ui_story_5030_50300004_49_dialog_content = "¡Es tan pequeño y lindo! Debe ser bastante joven, ¿eh?",
  ui_story_5030_50300004_50_dialog_content = "Entonces, ¿vendes fideos aquí?",
  ui_story_5030_50300004_51_dialog_content = "¡Vamos, pongámonos en fila!",
  ui_story_5030_50300004_52_dialog_content = "Ahora hay más gente...",
  ui_story_5030_50300004_53_dialog_content = "Parece que Sunstone realmente sabe cómo atraer a una multitud.",
  ui_story_5030_50300004_54_dialog_content = "Mmm...",
  ui_story_5030_50300004_55_dialog_content = "Leona? ¿Puedo pedir un favor?",
  ui_story_5030_50300004_56_dialog_content = "Ejem, si no tienes nada más que hacer hoy...",
  ui_story_5030_50300004_57_dialog_content = "En seguida.",
  ui_story_5030_50300004_58_dialog_content = "Tenga la seguridad de que me quedaré hasta que esté un poco menos ocupado.",
  ui_story_5030_50300004_59_dialog_content = "Ahora, no pongas esos ojos de cachorrito.",
  ui_story_5030_50300004_60_dialog_content = "Ve a ocuparte de los negocios.",
  ui_story_5030_50300004_61_dialog_content = "Cierto.",
  ui_story_5030_50300004_62_dialog_content = "¡Próximo cliente, por favor!",
  ui_story_5030_50300004_63_dialog_content = "¿Qué tipo quieres?",
  ui_story_5030_50300005_1_dialog_content = "Este es tu pan. Aquí estás.",
  ui_story_5030_50300005_2_dialog_content = "Caramba, eso está un poco caliente recién salido del horno...",
  ui_story_5030_50300005_3_dialog_content = "Déjame envolverlo muy bien para ti.",
  ui_story_5030_50300005_4_dialog_content = "¿Eh? ¿Un cliente quiere mi autógrafo? ¡Por supuesto!",
  ui_story_5030_50300005_5_dialog_content = "¿Dónde quieres que firme?",
  ui_story_5030_50300005_6_dialog_content = "¡Nosotros también queremos uno! ¡Nosotros también!",
  ui_story_5030_50300005_7_dialog_content = "Eso no es un problema, pero ¿podría pedirles a todos que sean un poco pacientes? ¡Hay una fila bastante larga!",
  ui_story_5030_50300005_8_dialog_content = "¿Quieres diez? Ya veo...",
  ui_story_5030_50300005_9_dialog_content = "Estimados invitados, estoy seguro de que ya han captado la verdadera esencia del hielo raspado.",
  ui_story_5030_50300005_10_dialog_content = "Probar diferentes sabores de hielo raspado no solo ampliará tus horizontes gustativos, sino que también te ayudará a desarrollar un físico saludable.",
  ui_story_5030_50300005_11_dialog_content = "Wow, es realmente delicioso...!",
  ui_story_5030_50300005_12_dialog_content = "¿Por qué dice \"únete a nosotros\" en tu cartel?",
  ui_story_5030_50300005_13_dialog_content = "Desde que entré en el concierto de hielo raspado, las cajas no han dejado de sonar.",
  ui_story_5030_50300005_14_dialog_content = "Convertirse en franquiciado significa que puedes ganar tanto dinero como yo.",
  ui_story_5030_50300005_15_dialog_content = "¡Apreciados invitados, aprendan los trucos del oficio y únanse al apasionante mundo del hielo raspado!",
  ui_story_5030_50300005_16_dialog_content = "Suena bastante bien... ¿Deberíamos comprar uno primero y probarlo?",
  ui_story_5030_50300005_17_dialog_content = "Sí, probemos uno.",
  ui_story_5030_50300005_18_dialog_content = "Aquí está el tuyo.",
  ui_story_5030_50300005_19_dialog_content = "¡Y aquí está el tuyo!",
  ui_story_5030_50300005_20_dialog_content = "¡Sea un consumidor racional y reduzca el desperdicio! ¿Entiendo?",
  ui_story_5030_50300005_21_dialog_content = "¡La barbacoa a la parrilla es realmente novedosa!",
  ui_story_5030_50300005_22_dialog_content = "¡Yo! ¡Dame uno también, por favor!",
  ui_story_5030_50300005_23_dialog_content = "Bueno, ¡el negocio se ve bastante bien para todos!",
  ui_story_5030_50300005_24_dialog_content = "A continuación, ¡esta es Rainbow con más detalles sobre la competencia!",
  ui_story_5030_50300005_25_dialog_content = "El propietario actual del puesto mejor clasificado es el Sr. Fleur!",
  ui_story_5030_50300005_26_dialog_content = "Ja, eso no es exactamente una sorpresa. Basta con mirar la línea en el frente.",
  ui_story_5030_50300005_27_dialog_content = "Llegando en segundo lugar, el Sr. Kleken!",
  ui_story_5030_50300005_28_dialog_content = "Si bien el hielo raspado es, sin duda, difícil de almacenar, sus excelentes habilidades de marketing le han dado un gran resultado.",
  ui_story_5030_50300005_29_dialog_content = "En tercer lugar, la Sra. Smokey!",
  ui_story_5030_50300005_30_dialog_content = "Si bien puede ser un poco amargada, ¡no se puede negar que su negocio ha sido excelente!",
  ui_story_5030_50300005_31_dialog_content = "¡Parece que todos hicieron todo lo posible, solo para tener en sus manos este Sorcery Pot!",
  ui_story_5030_50300005_32_dialog_content = "Vaya, ¡casi olvido nuestro nombre de jugador!",
  ui_story_5030_50300005_33_dialog_content = "¡Bien! En realidad, el resultado de PlayerName también es bastante bueno.",
  ui_story_5030_50300005_34_dialog_content = "Si bien su resultado no deslumbró tanto como nuestros tres primeros, no hay duda de que con un poco de trabajo duro, ¡la victoria es posible!",
  ui_story_5030_50300005_35_dialog_content = "¡Eh... jajaja...!",
  ui_story_5030_50300005_36_dialog_content = "¡Bueno, ese es el final de la transmisión del medio tiempo!",
  ui_story_5030_50300005_37_dialog_content = "¡La próxima vez que nos encontremos, será el momento de anunciar los resultados de la competencia!",
  ui_story_5030_50300005_38_dialog_content = "¡Para conseguir ese misterioso utensilio de cocina y hacer tus sueños realidad!",
  ui_story_5030_50300005_39_dialog_content = "¡Vamos, todos!",
  ui_story_5030_50300005_40_dialog_content = "¡Anímate y participa!",
  ui_story_5030_50300005_41_dialog_content = "Uf... Estoy sintiendo la presión.",
  ui_story_5030_50300005_42_dialog_content = "También hay menos clientes, ya que Leona izquierda.",
  ui_story_5030_50300005_43_dialog_content = "Efectivamente, vinieron hasta aquí para comer fideos solo para ver a ese dragón que escupe fuego...",
  ui_story_5030_50300005_44_dialog_content = "Esto no parece funcionar.",
  ui_story_5030_50300005_45_dialog_content = "Pareces bastante preocupado en este momento.",
  ui_story_5030_50300005_46_dialog_content = "Tengo curiosidad, PlayerName, ¿por qué problemas estás atrapado?",
  ui_story_5030_50300005_47_dialog_content = "Hola, Genevieve.",
  ui_story_5030_50300005_48_dialog_content = "Ah, ¿viniste por los fideos?",
  ui_story_5030_50300005_49_dialog_content = "Espera. Lo tengo. Estás buscando a alguien, ¿verdad?",
  ui_story_5030_50300005_50_dialog_content = "Bueno, ahí está ella...",
  ui_story_5030_50300005_51_dialog_content = "¡Oye, espera! ¡Espera un segundo!",
  ui_story_5030_50300005_52_dialog_content = "¿Qué estás pensando, pobre PlayerName?",
  ui_story_5030_50300005_53_dialog_content = "Solo estoy aquí para ayudarte.",
  ui_story_5030_50300005_54_dialog_content = "¿Ayúdame?",
  ui_story_5030_50300005_55_dialog_content = "Oh, ahora recuerdo. ¿No eres también bastante hábil con el fuego...?",
  ui_story_5030_50300005_56_dialog_content = "¿Te ayuda a hervir el agua más rápido, luego enjuagar y repetir?",
  ui_story_5030_50300005_57_dialog_content = "Aun así, eso es solo una repetición de los resultados recientes, no una gran mejora.",
  ui_story_5030_50300005_58_dialog_content = "Tú, deberías mirar el panorama general.",
  ui_story_5030_50300005_59_dialog_content = "La gente viene aquí por algo fresco y nuevo, ¿verdad?",
  ui_story_5030_50300005_60_dialog_content = "Piénsalo.",
  ui_story_5030_50300005_61_dialog_content = "Imagínese si su puesto no solo ofreciera sustento, sino que también proporcionara algunos extras para los clientes cansados.",
  ui_story_5030_50300005_62_dialog_content = "¿A qué te refieres con \"extras\"?",
  ui_story_5030_50300005_63_dialog_content = "U-Um, Genevieve, estamos en el territorio de Lumopolis. Este no es territorio de True Order o Umbraton.",
  ui_story_5030_50300005_64_dialog_content = "¿No seremos arrestados si lo llevamos demasiado lejos?",
  ui_story_5030_50300005_65_dialog_content = "¿Acerca de?",
  ui_story_5030_50300005_66_dialog_content = "Por \"extras\", me refiero a mejores servicios al cliente como mantenimiento de línea y masajes.",
  ui_story_5030_50300005_67_dialog_content = "¡Oh, ESE tipo de servicios!",
  ui_story_5030_50300005_68_dialog_content = "¡Pensé que querías que echara un poco de ginebra o algo así!",
  ui_story_5030_50300005_69_dialog_content = "¡Esperemos hasta la noche para ese tipo de cosas!",
  ui_story_5030_50300005_70_dialog_content = "Hace demasiado calor para beber ahora de todos modos, y es imposible saborear la delicia de la ginebra.",
  ui_story_5030_50300005_71_dialog_content = "Muy bien, bueno, gracias por tu sugerencia, Genevieve...",
  ui_story_5030_50300005_72_dialog_content = "P-Pero, ¿la cosa es que realmente no tengo manos libres para ofrecer tales servicios?",
  ui_story_5030_50300005_73_dialog_content = "No necesito tus manos.",
  ui_story_5030_50300005_74_dialog_content = "Ya tengo un monton de \"lacayos\" prestando manos...",
  ui_story_5030_50300005_75_dialog_content = "Dama Genevieve! Dama Genevieve!!",
  ui_story_5030_50300006_1_dialog_content = "(Debe estar realmente horneándose en este momento).",
  ui_story_5030_50300006_2_dialog_content = "(Acabo de sentir el sudor goteando de mi barbilla...)",
  ui_story_5030_50300006_3_dialog_content = "(Si escucho con atención, probablemente podría escuchar esa gota de sudor caer al suelo).",
  ui_story_5030_50300006_4_dialog_content = "(Al menos todavía hay una brisa, incluso en un día tan caluroso...)",
  ui_story_5030_50300006_5_dialog_content = "(No puedo sentir el fresco alivio que trae el viento... o incluso sentir el viento mismo).",
  ui_story_5030_50300006_6_dialog_content = "(Eh... Entonces, ¿cómo sé que incluso está soplando?)",
  ui_story_5030_50300006_7_dialog_content = "(Bueno, deben haber sido esas tres hojas revoloteando en el aire frente a mí).",
  ui_story_5030_50300006_8_dialog_content = "(Tres hojas... Manchas de agua en el suelo. Y un plato que alguien rompió accidentalmente... ¿Eh?)",
  ui_story_5030_50300006_9_dialog_content = "(Un par de zapatos aparecieron en el suelo. Los dedos puntiagudos de ellos se detienen frente a mí...)",
  ui_story_5030_50300006_10_dialog_content = "Espera... ¿Dedos puntiagudos, deteniéndote frente a mi puesto de ramen?",
  ui_story_5030_50300006_11_dialog_content = "Entonces eso significa...",
  ui_story_5030_50300006_12_dialog_content = "¡Un invitado! ¡UN INVITADO tan esperado!",
  ui_story_5030_50300006_13_dialog_content = "Estimado invitado, por favor, eche un vistazo! ¡Mira nuestros fideos!",
  ui_story_5030_50300006_14_dialog_content = "El negocio no parece muy dinámico.",
  ui_story_5030_50300006_15_dialog_content = "Eh... ¿Jeno?",
  ui_story_5030_50300006_16_dialog_content = "¿Estás aquí por los fideos?",
  ui_story_5030_50300006_17_dialog_content = "¿O estás haciendo las rondas como anfitrión...?",
  ui_story_5030_50300006_18_dialog_content = "Estoy aquí por los fideos.",
  ui_story_5030_50300006_19_dialog_content = "... ¡Vaya! Ya veo.",
  ui_story_5030_50300006_20_dialog_content = "¿Y qué tipo de fideos buscas?",
  ui_story_5030_50300006_21_dialog_content = "No hay mucha gente aquí en este momento, así que podría dejarte probarlos todos...",
  ui_story_5030_50300006_22_dialog_content = "Un plato de sopa de fideos está bien.",
  ui_story_5030_50300006_23_dialog_content = "Gracias.",
  ui_story_5030_50300006_24_dialog_content = "¡Por supuesto! Ya viene...",
  ui_story_5030_50300006_25_dialog_content = "¿Entonces, qué piensas? ¿Esta bien?",
  ui_story_5030_50300006_26_dialog_content = "bastante delicioso",
  ui_story_5030_50300006_27_dialog_content = "Que bueno escucharlo.",
  ui_story_5030_50300006_28_dialog_content = "Así que no puedo entender por qué su negocio es tan lento en este momento.",
  ui_story_5030_50300006_29_dialog_content = "Seguramente debería haber más demanda para este tipo de cosas, ¿verdad?",
  ui_story_5030_50300006_30_dialog_content = "Para ser honesto, el negocio no estaba tan mal en este momento...",
  ui_story_5030_50300006_31_dialog_content = "Es solo que los invitados parecían más atraídos por los extras.",
  ui_story_5030_50300006_32_dialog_content = "¿Extras?",
  ui_story_5030_50300006_33_dialog_content = "Hmm... Tal vez sea mejor decir trucos para impulsar el negocio.",
  ui_story_5030_50300006_34_dialog_content = "Como el dragón que escupe fuego o mejores servicios al cliente. Ese tipo de cosas.",
  ui_story_5030_50300006_35_dialog_content = "Bueno, ¿los fideos saben diferente?",
  ui_story_5030_50300006_36_dialog_content = "Más o menos lo mismo, supongo. Su ramen y los que se vendieron antes se hicieron exactamente de la misma manera.",
  ui_story_5030_50300006_37_dialog_content = "Debes haber tenido un montón de clientes, ¿verdad?",
  ui_story_5030_50300006_38_dialog_content = "Sí. Definitivamente había una larga fila.",
  ui_story_5030_50300006_39_dialog_content = "Debe estar ansioso por servir fideos a cada cliente incluso más rápido en ese entonces, supongo.",
  ui_story_5030_50300006_40_dialog_content = "Bueno, eso también es un hecho...",
  ui_story_5030_50300006_41_dialog_content = "Hmm... creo que entiendo lo que estás tratando de decir.",
  ui_story_5030_50300006_42_dialog_content = "Debido a que tenía tanta prisa, era difícil evitar errores.",
  ui_story_5030_50300006_43_dialog_content = "Y debido a eso, no hay posibilidad de hacer esas porciones al mismo nivel que lo que acaba de comer.",
  ui_story_5030_50300006_44_dialog_content = "No... Quiero decir, creo que deberías centrarte más en la comida en sí.",
  ui_story_5030_50300006_45_dialog_content = "El estrés relacionado con las largas filas es solo un problema.",
  ui_story_5030_50300006_46_dialog_content = "Pero la conclusión es que simplemente no puede atender a tanta gente.",
  ui_story_5030_50300006_47_dialog_content = "Quizás. Pero no tienen la paciencia para esperar mucho tiempo.",
  ui_story_5030_50300006_48_dialog_content = "¿Qué tal si les avisamos del tiempo de espera aproximado?",
  ui_story_5030_50300006_49_dialog_content = "Los clientes atraídos por los extras estarían aún más impacientes.",
  ui_story_5030_50300006_50_dialog_content = "creo que es una paradoja...",
  ui_story_5030_50300006_51_dialog_content = "Verás, el punto es que quiero poner mis manos en esa olla. Y para que eso suceda, cuantas más ventas, mejor.",
  ui_story_5030_50300006_52_dialog_content = "Entonces crees que los extras son solo algo que tienes que hacer.",
  ui_story_5030_50300006_53_dialog_content = "Pero, ¿puede garantizar que todas las personas atraídas por los extras realmente compren sus fideos?",
  ui_story_5030_50300006_54_dialog_content = "...",
  ui_story_5030_50300006_55_dialog_content = "Bueno, yo... No.",
  ui_story_5030_50300006_56_dialog_content = "Es solo que me pongo aún más nervioso cuando veo tanta gente esperando.",
  ui_story_5030_50300006_57_dialog_content = "Y un poco ansioso.",
  ui_story_5030_50300006_58_dialog_content = "Todo en lo que puedo pensar es en terminar un tazón, y luego el siguiente, y el siguiente...",
  ui_story_5030_50300006_59_dialog_content = "Lo digo en serio cuando dije que este plato de fideos que tenía delante estaba delicioso.",
  ui_story_5030_50300006_60_dialog_content = "No me atrevo a decir, \"las cabezas frías producen fideos calientes\".",
  ui_story_5030_50300006_61_dialog_content = "O \"Concéntrate en la comida, olvídate del mundo\", esos eslóganes trillados.",
  ui_story_5030_50300006_62_dialog_content = "Bueno, todo lo que quiero decir es: este tazón de fideos es bastante delicioso.",
  ui_story_5030_50300006_63_dialog_content = "Si sé que alguien tiene la intención de abrir un restaurante en el futuro, le indicaré su dirección para obtener consejos sobre cómo hacer fideos.",
  ui_story_5030_50300006_64_dialog_content = "Mmm...",
  ui_story_5030_50300006_65_dialog_content = "Gracias, Jeno.",
  ui_story_5030_50300006_66_dialog_content = "¿Es esto lo que pensabas cuando comenzaste a actuar?",
  ui_story_5030_50300006_67_dialog_content = "Ya sabes, no prestes atención al tamaño de la audiencia, sino solo concéntrate en la magia.",
  ui_story_5030_50300006_68_dialog_content = "En seguida.",
  ui_story_5030_50300006_69_dialog_content = "La magia es mi vida. No me importa nada más.",
  ui_story_5030_50300006_70_dialog_content = "Tengo que decir que ese tipo de actitud mola.",
  ui_story_5030_50300006_71_dialog_content = "Tienes algunos invitados más.",
  ui_story_5030_50300006_72_dialog_content = "Si me disculpas. Espero tus milagros.",
  ui_story_5030_50300006_73_dialog_content = "Centrarse en la comida en sí...?",
  ui_story_5030_50300006_74_dialog_content = "Los fideos eran geniales. ¡Toma estos ingredientes como agradecimiento!",
  ui_story_5030_50300006_75_dialog_content = "Puedo asegurarles que esto fue hecho usando plantas que recolecté minuciosamente durante un largo período de tiempo.",
  ui_story_5030_50300006_76_dialog_content = "¿Ver? Huele maravilloso, ¿no?",
  ui_story_5030_50300006_77_dialog_content = "¡Este libro de cocina secreto es para ti!",
  ui_story_5030_50300006_78_dialog_content = "Seguro que no nos defraudarás, ¿verdad, PlayerName?",
  ui_story_5030_50300006_79_dialog_content = "¡Ay! ¡Lo entiendo!",
  ui_story_5030_50300007_1_dialog_content = "¿Escuchaste? ¡Esa leyenda absoluta también participará!",
  ui_story_5030_50300007_2_dialog_content = "tío johnny? ¡¿Quieres decir que el tío Johnny viene aquí, en persona?!",
  ui_story_5030_50300007_3_dialog_content = "No, no... Creo que su nombre era algo así como Noodle God.",
  ui_story_5030_50300007_4_dialog_content = "Mi amigo fue a probar el puesto de Noodle God. Veredicto: ¡nunca ha comido fideos tan deliciosos en toda su vida!",
  ui_story_5030_50300007_5_dialog_content = "¿En serio? Eso suena divino. Creo que quiero probar algunos, también.",
  ui_story_5030_50300007_6_dialog_content = "Mira, justo allí—",
  ui_story_5030_50300007_7_dialog_content = "203! ¡Ese soy yo! ¡Número de pedido 203!",
  ui_story_5030_50300007_8_dialog_content = "Te han engañado, amigo. Creo que encontrarás que tengo 203.",
  ui_story_5030_50300007_9_dialog_content = "Viendo que los 203 están peleando, ¿por qué no me lo das? ¡Tengo 204!",
  ui_story_5030_50300007_10_dialog_content = "Wow... ¿Demasiada gente en la fila...?",
  ui_story_5030_50300007_11_dialog_content = "(Me duelen los brazos...)",
  ui_story_5030_50300007_12_dialog_content = "(Ni siquiera estoy seguro de poder hacer algo tan básico como entregar los tazones...)",
  ui_story_5030_50300007_13_dialog_content = "(Pero si no fuera por eso...)",
  ui_story_5030_50300007_14_dialog_content = "(¡Para mi último sueño!)",
  ui_story_5030_50300007_15_dialog_content = "(¡Para permitir que todos en Cloud Gardens y Colossus disfruten de fideos deliciosos y convenientes!)",
  ui_story_5030_50300007_16_dialog_content = "-¡Oye! 204! ¡Estás despierto!",
  ui_story_5030_50300007_17_dialog_content = "¡Guau! ¡Parece que está zumbando por aquí, PlayerName!",
  ui_story_5030_50300007_18_dialog_content = "Uh, también estás aquí por los fideos, Rainbow?",
  ui_story_5030_50300007_19_dialog_content = "No esta vez. ¡Estoy aquí para hacer un anuncio de competencia!",
  ui_story_5030_50300007_20_dialog_content = "¡FELICITACIONES, PlayerName!",
  ui_story_5030_50300007_21_dialog_content = "¿Felicitarme?",
  ui_story_5030_50300007_22_dialog_content = "¿Me estás diciendo que lo hice?",
  ui_story_5030_50300007_23_dialog_content = "¡Ahora estás en segundo lugar!",
  ui_story_5030_50300007_24_dialog_content = "... ¿Por qué exactamente me estás felicitando entonces?",
  ui_story_5030_50300007_25_dialog_content = "¿Eh? ¡Estuviste cuarto al final de la última ronda!",
  ui_story_5030_50300007_26_dialog_content = "¡Ese es un progreso digno de felicitación si alguna vez hubo alguno!",
  ui_story_5030_50300007_27_dialog_content = "Bueno, si insistes en ponerlo así...",
  ui_story_5030_50300007_28_dialog_content = "¿Quién está en primer lugar?",
  ui_story_5030_50300007_29_dialog_content = "Solo el fundador del imperio del pan, el Sr. Fleur!",
  ui_story_5030_50300007_30_dialog_content = "Estamos en la última media hora de la competencia. ¿Puede el trabajo duro ayudar a PlayerName a superar la línea?",
  ui_story_5030_50300007_31_dialog_content = "Ciertamente lo intentaré.",
  ui_story_5030_50300007_32_dialog_content = "¿Está listo? ¿Ya estoy despierto? tengo 205!",
  ui_story_5030_50300007_33_dialog_content = "¡Un segundo, casi listo!",
  ui_story_5030_50300007_34_dialog_content = "¡Increíble! A pesar de que estaba hablando con el anfitrión, ¡sus manos nunca se detuvieron!",
  ui_story_5030_50300007_35_dialog_content = "¿Es este el talento secreto del Dios de los Fideos?",
  ui_story_5030_50300007_36_dialog_content = "¿Dios de los fideos?",
  ui_story_5030_50300007_37_dialog_content = "¡Hola!",
  ui_story_5030_50300007_38_dialog_content = "¿Puedo preguntar a quién te refieres con \"Dios de los fideos\"?",
  ui_story_5030_50300007_39_dialog_content = "Uh, solo el dueño de este puesto de fideos.",
  ui_story_5030_50300007_40_dialog_content = "Wow, ahora ¡ESO ES una fila larga!",
  ui_story_5030_50300007_41_dialog_content = "Es solo porque sus fideos son tan sabrosos.",
  ui_story_5030_50300007_42_dialog_content = "¿Dios de los fideos? Pff...",
  ui_story_5030_50300007_43_dialog_content = "¡Claramente, solo Anzu y Momo son dignos de tal epíteto!",
  ui_story_5030_50300007_44_dialog_content = "¡Creo que será mejor que eche un vistazo más de cerca a este tipo, para ver cuán hábil es!",
  ui_story_5030_50300007_45_dialog_content = "¡Próximo! ¡Hola! ¿Qué sabor te gustaría—",
  ui_story_5030_50300007_46_dialog_content = "... Yao?!",
  ui_story_5030_50300007_47_dialog_content = "¡Vaya ahora! Dios mio...!",
  ui_story_5030_50300007_48_dialog_content = "Espera un minuto... ¿Me estás diciendo que ERES el Dios de los Fideos del que estaban hablando?",
  ui_story_5030_50300007_49_dialog_content = "Bueno, escucha, puede que yo sea el que todo el mundo llame así pero, pero... ¡No es como si me promocionara de esa manera!",
  ui_story_5030_50300007_50_dialog_content = "Entonces, ¿realmente es su cocina la que ha impresionado a todos?",
  ui_story_5030_50300007_51_dialog_content = "Quiero decir, ¿sí? Probablemente...",
  ui_story_5030_50300007_52_dialog_content = "¿Venir aquí era parte de sus viajes?",
  ui_story_5030_50300007_53_dialog_content = "¡Sí! ¡Quería echar un vistazo!",
  ui_story_5030_50300007_54_dialog_content = "Pero debo decir que es una vista un poco extraña: ¡tú, solo, cocinando fideos!",
  ui_story_5030_50300007_55_dialog_content = "¡Oh! Así que es para ese Sorcery Pot, ¿eh? No es de extrañar que acabo de ver Kleken Por ahí...",
  ui_story_5030_50300007_56_dialog_content = "¡Guau, qué motivación inesperadamente noble para ganar, PlayerName!",
  ui_story_5030_50300007_57_dialog_content = "Woo... Boo-hoo... Te siento. ¡No digas más, PlayerName!",
  ui_story_5030_50300007_58_dialog_content = "Tiene que haber al menos 20 personas detrás de mí. ¿Cuántos pedidos más puedes hacer?",
  ui_story_5030_50300007_59_dialog_content = "Hmm... ¿podrías manejar 87?",
  ui_story_5030_50300007_60_dialog_content = "Tenga la seguridad de que estos 87 tazones...",
  ui_story_5030_50300007_61_dialog_content = "TODOS ESTÁN AHORA CONTRATADOS POR MÍ!",
  ui_story_5030_50300007_62_dialog_content = "¿Quién es el proveedor de los fideos y los aderezos?",
  ui_story_5030_50300007_63_dialog_content = "¡Déjame comprar todos los ingredientes crudos también!",
  ui_story_5030_50300007_64_dialog_content = "Yao, escucha, yo...",
  ui_story_5030_50300007_65_dialog_content = "¡Ehh, no hace falta que me lo agradezcas!",
  ui_story_5030_50300007_66_dialog_content = "Para un sueño tan grandioso... ¡Simplemente debo echar una mano!",
  ui_story_5030_50300007_67_dialog_content = "Además soy fenomenalmente rico, ¡jaja!",
  ui_story_5030_50300007_68_dialog_content = "¡Comienza la cuenta regresiva final—!",
  ui_story_5030_50300007_69_dialog_content = "¡Guau, todos los concursantes están dando un paso al frente!",
  ui_story_5030_50300007_70_dialog_content = "En este momento increíblemente tenso, ¡TRES!",
  ui_story_5030_50300007_71_dialog_content = "¡Los datos de contacto escritos de Kleken para invertir en su propio tentáculo!",
  ui_story_5030_50300007_72_dialog_content = "Esta es una espera angustiosa para ver los resultados: ¡DOS!",
  ui_story_5030_50300007_73_dialog_content = "Fleur ¡una vez más ha mostrado esa sonrisa ganadora de marca registrada a sus fanáticos!",
  ui_story_5030_50300007_74_dialog_content = "La emoción es casi demasiado para manejar: ¡UNO!",
  ui_story_5030_50300007_75_dialog_content = "Por la presente declaro que el campeón de esta batalla por el Olla Hechicera será—",
  ui_story_5030_50300007_76_dialog_content = "¡PlayerName!",
  ui_story_5030_50300007_77_dialog_content = "PlayerName, que vendió una increíble cantidad de fideos, ¡todo en pos de su gran sueño!",
  ui_story_5030_50300007_78_dialog_content = "¡Felicitamos a PlayerName por ganar este misterioso e intrigante Sorcery Pot!",
  ui_story_5030_50300007_79_dialog_content = "Felicitaciones, PlayerName.",
  ui_story_5030_50300007_80_dialog_content = "¡Así que PlayerName ganó!",
  ui_story_5030_50300007_81_dialog_content = "¿Sabes cómo usarlo?",
  ui_story_5030_50300007_82_dialog_content = "Err... Gracias a todos.",
  ui_story_5030_50300007_83_dialog_content = "Creo que necesito pasar tiempo explorando cómo usarlo.",
  ui_story_5030_50300007_84_dialog_content = "Creo que he visto este tipo de utensilios de cocina antes, pero esta olla...",
  ui_story_5030_50300007_85_dialog_content = "Uh, no sabes cómo usarlo, ¿verdad?",
  ui_story_5030_50300007_86_dialog_content = "¡Solo necesito refrescar mi memoria!",
  ui_story_5030_50300007_87_dialog_content = "(¿Cómo enciendo exactamente la cocción automática?)",
  ui_story_5030_50300007_88_dialog_content = "(¿Me vería un poco estúpido si tratara de sentirlo?)",
  ui_story_5030_50300007_89_dialog_content = "¿Puedo ver?",
  ui_story_5030_50300007_90_dialog_content = "Por supuesto.",
  ui_story_5030_50300007_91_dialog_content = "No tengo ni idea. Esto es totalmente diferente a cualquier otro utensilio de cocina que haya visto...",
  ui_story_5030_50300007_92_dialog_content = "Um... Pero su exquisita estructura realmente hace que uno desee saber cómo funciona.",
  ui_story_5030_50300007_93_dialog_content = "PlayerName, cuando hayas logrado tu sueño, ¿podría prestarme este utensilio de cocina por un par de días?",
  ui_story_5030_50300007_94_dialog_content = "¡No hay problema! Solo tengo que averiguar cómo funciona la cosa, primero...",
  ui_story_5030_50300007_95_dialog_content = "Creo que necesita algún tipo de empujón externo para ponerse en marcha.",
  ui_story_5030_50300007_96_dialog_content = "¿Fuego? ¿Necesita fuego?",
  ui_story_5030_50300007_97_dialog_content = "¿No puede hacer daño intentarlo?",
  ui_story_5030_50300007_98_dialog_content = "... Eso va demasiado lejos, ¿no?!",
  ui_story_5030_50300007_99_dialog_content = "Pero mira, no hay daños.",
  ui_story_5030_50300007_100_dialog_content = "¿Qué tal... probar un poco de agua?",
  ui_story_5030_50300007_101_dialog_content = "...",
  ui_story_5030_50300007_102_dialog_content = "¡Arde con las olas del mar!",
  ui_story_5030_50300007_103_dialog_content = "Se queda quieto.",
  ui_story_5030_50300007_104_dialog_content = "Er, ¿tal vez necesita un tipo de fuerza más suave y controlada?",
  ui_story_5030_50300007_105_dialog_content = "¡Estoy Aquí!",
  ui_story_5030_50300007_106_dialog_content = "Parece duro como una roca.",
  ui_story_5030_50300007_107_dialog_content = "Ce-ce...",
  ui_story_5030_50300007_108_dialog_content = "No puedes usar el pensamiento moderno para entender este tipo de cosas antiguas de las ruinas...",
  ui_story_5030_50300007_109_dialog_content = "Pero, ¿cómo lo sabremos si no lo intentamos?",
  ui_story_5030_50300007_110_dialog_content = "Bueno... ¿Intentar atacar con Lumina?",
